import os, sys, json
from datetime import datetime, timedelta, timezone
sys.path.insert(0, os.path.abspath("."))
os.environ["STAGE"] = "prod"; os.environ["DRY_RUN"] = "true"
from utils.boto import get_connections_row, org_decrypt, get_org_private_key
from utils.integrations import get_integration_file

CONNS = sys.argv[1:]
end = datetime.now(timezone.utc)
start = end - timedelta(days=2)
for conn in CONNS:
    print(f"\n######## {conn}")
    try:
        row = get_connections_row(conn)
        secret = org_decrypt(row["integration_secret"], get_org_private_key(row["org_id"]))
        f = get_integration_file(row["integration_name"], row["integration_type"])
        i = f.Integration(connection_id=conn, org_id=row["org_id"], integration_secret=secret,
                          connection_additional_fields=row.get("additional_fields"), customer_id=row.get("customer_id"))
        rsp = i.packiyo_request("orders", params={
            "page[size]": 100, "page[number]": 1,
            "filter[updated_at_min]": start.strftime("%Y-%m-%dT%H:%M:%S"),
            "filter[updated_at_max]": end.strftime("%Y-%m-%dT%H:%M:%S"),
            "include": "shipments,shipments.packages,shipments.shipment_trackings",
        })
    except Exception as e:
        print("ERR", repr(e)[:300]); continue
    inc = {}
    for x in rsp.get("included", []):
        inc[(x["type"], x["id"])] = x
    shipments = [v for k, v in inc.items() if k[0] == "shipments"]
    print("orders", len(rsp["data"]), "shipments", len(shipments))
    shown = 0
    for s in shipments:
        pkgs = s["relationships"]["packages"]["data"]
        if len(pkgs) < 2:
            continue
        print("\n-- shipment", s["id"], "attrs:", json.dumps(s["attributes"]))
        for p in pkgs:
            pk = inc.get(("packages", p["id"]))
            print("   package", p["id"], json.dumps(pk["attributes"]) if pk else "NOT INCLUDED")
        for t in s["relationships"]["shipment_trackings"]["data"]:
            tk = inc.get(("shipment-trackings", t["id"]))
            print("   tracking", t["id"], json.dumps(tk["attributes"]) if tk else "NOT INCLUDED")
        shown += 1
        if shown >= 3:
            break
